-- Fixed, bounded review approval. No credential reads and no Pin dispatch.
begin;
set local statement_timeout='20s';
set local lock_timeout='5s';
select pg_advisory_xact_lock(1617125,13);
create temporary table reviewed_input as select * from jsonb_to_recordset('[{"queue_id": "0a6c060c-911e-4f73-b04b-1921863b80bc", "shop": "CellaHo", "listing_id": "1832656370", "source_url": "https://www.etsy.com/listing/1832656370/floral-embroidered-jacquard-fabric", "category": "Embroidered Fabric", "image_url": "https://i.etsystatic.com/39663062/r/il/9d2aff/6565631907/il_794xN.6565631907_30g9.jpg", "destination_url": "https://www.etsy.com/listing/1832656370/floral-embroidered-jacquard-fabric", "title": "Floral Embroidered Jacquard Fabric: Lightweight Cotton Polyester Blend", "body": "Floral Embroidered Jacquard Fabric: Lightweight Cotton Polyester Blend. Fabric for sewing projects from CellaHo. View the original Etsy listing for options and current details.", "handle": "mydecorshop", "mapped": true, "history_count": 0, "review_exists": false, "board_id": "499618221101238533", "new_title": "Floral Embroidered Jacquard Fabric: Lightweight Cotton Polyester Blend", "new_body": "Floral Embroidered Jacquard Fabric: Lightweight Cotton Polyester Blend. Fabric for sewing projects from CellaHo. View the original Etsy listing for options and current details.", "new_image_url": "https://i.etsystatic.com/39663062/r/il/9d2aff/6565631907/il_794xN.6565631907_30g9.jpg", "checked_at": "2026-10-13T02:58:13.875Z"}, {"queue_id": "fcffce67-24e9-42c8-b143-133d9f5ba21b", "shop": "CellaHo", "listing_id": "1839182756", "source_url": "https://www.etsy.com/listing/1839182756/black-cotton-fabric-white-floral", "category": "Embroidered Fabric", "image_url": "https://i.etsystatic.com/39663062/r/il/241e8c/6590990661/il_794xN.6590990661_ijqz.jpg", "destination_url": "https://www.etsy.com/listing/1839182756/black-cotton-fabric-white-floral", "title": "Black Cotton Fabric: White Floral Embroidery, Elegant Dress Material", "body": "Black Cotton Fabric: White Floral Embroidery, Elegant Dress Material. Fabric for sewing projects from CellaHo. View the original Etsy listing for options and current details.", "handle": "mydecorshop", "mapped": true, "history_count": 0, "review_exists": false, "board_id": "499618221101238533", "new_title": "Black Cotton Fabric: White Floral Embroidery, Elegant Dress Material", "new_body": "Black Cotton Fabric: White Floral Embroidery, Elegant Dress Material. Fabric for sewing projects from CellaHo. View the original Etsy listing for options and current details.", "new_image_url": "https://i.etsystatic.com/39663062/r/il/241e8c/6590990661/il_794xN.6590990661_ijqz.jpg", "checked_at": "2026-10-13T02:58:15.251Z"}, {"queue_id": "5e9c3f0f-ba2f-4e3d-bfcd-1ae2a6f581c7", "shop": "CellaHo", "listing_id": "1846855145", "source_url": "https://www.etsy.com/listing/1846855145/floral-embroidered-linen-fabric", "category": "Embroidered Fabric", "image_url": "https://i.etsystatic.com/39663062/r/il/b70a95/6565640863/il_794xN.6565640863_6ngq.jpg", "destination_url": "https://www.etsy.com/listing/1846855145/floral-embroidered-linen-fabric", "title": "Floral Embroidered Linen Fabric: Lightweight Sewing Material", "body": "Floral Embroidered Linen Fabric: Lightweight Sewing Material. Fabric for sewing projects from CellaHo. View the original Etsy listing for options and current details.", "handle": "mydecorshop", "mapped": true, "history_count": 0, "review_exists": false, "board_id": "499618221101238533", "new_title": "Floral Embroidered Fabric for Home Decor Sewing", "new_body": "Floral Embroidered Fabric for Home Decor Sewing. Fabric for sewing projects from CellaHo. View the original Etsy listing for options and current details.", "new_image_url": "https://i.etsystatic.com/39663062/r/il/b70a95/6565640863/il_794xN.6565640863_6ngq.jpg", "checked_at": "2026-10-13T02:58:40.719Z"}, {"queue_id": "1fb92561-5600-4374-ac1d-9864310ce6a3", "shop": "CellaHo", "listing_id": "4365149143", "source_url": "https://www.etsy.com/listing/4365149143/boho-paisley-lace-fabric-embroidered", "category": "Embroidered Fabric", "image_url": "https://i.etsystatic.com/39663062/r/il/ea71ba/7177456250/il_794xN.7177456250_l1qz.jpg", "destination_url": "https://www.etsy.com/listing/4365149143/boho-paisley-lace-fabric-embroidered", "title": "Boho Paisley Lace Fabric: Embroidered Cotton Thread, Sheer Wedding Material", "body": "Boho Paisley Lace Fabric: Embroidered Cotton Thread, Sheer Wedding Material. Fabric for sewing projects from CellaHo. View the original Etsy listing for options and current details.", "handle": "mydecorshop", "mapped": true, "history_count": 0, "review_exists": false, "board_id": "499618221101238533", "new_title": "Boho Paisley Lace Fabric: Embroidered Cotton Thread, Sheer Wedding Material", "new_body": "Boho Paisley Lace Fabric: Embroidered Cotton Thread, Sheer Wedding Material. Fabric for sewing projects from CellaHo. View the original Etsy listing for options and current details.", "new_image_url": "https://i.etsystatic.com/39663062/r/il/ea71ba/7177456250/il_794xN.7177456250_l1qz.jpg", "checked_at": "2026-10-13T02:58:43.012Z"}, {"queue_id": "20be1fda-afe8-4629-a612-b527969dd516", "shop": "CellaHo", "listing_id": "4367385017", "source_url": "https://www.etsy.com/listing/4367385017/white-3d-embroidered-floral-lace-chiffon", "category": "Embroidered Fabric", "image_url": "https://i.etsystatic.com/39663062/r/il/0deda7/7236487151/il_794xN.7236487151_bud0.jpg", "destination_url": "https://www.etsy.com/listing/4367385017/white-3d-embroidered-floral-lace-chiffon", "title": "White 3D Embroidered Floral Lace Chiffon Mesh Fabric", "body": "White 3D Embroidered Floral Lace Chiffon Mesh Fabric. Fabric for sewing projects from CellaHo. View the original Etsy listing for options and current details.", "handle": "mydecorshop", "mapped": true, "history_count": 0, "review_exists": false, "board_id": "499618221101238533", "new_title": "White 3D Embroidered Floral Lace Chiffon Mesh Fabric", "new_body": "White 3D Embroidered Floral Lace Chiffon Mesh Fabric. Fabric for sewing projects from CellaHo. View the original Etsy listing for options and current details.", "new_image_url": "https://i.etsystatic.com/39663062/r/il/0deda7/7236487151/il_794xN.7236487151_bud0.jpg", "checked_at": "2026-10-13T02:58:57.957Z"}]'::jsonb) as x(queue_id uuid,shop text,listing_id text,source_url text,category text,image_url text,destination_url text,title text,body text,handle text,board_id text,new_title text,new_body text,checked_at timestamptz,new_image_url text);
select q.id from publish_queue q join reviewed_input x on x.queue_id=q.id for update of q;
select cv.id from content_variants cv join publish_queue q on q.content_variant_id=cv.id join reviewed_input x on x.queue_id=q.id for update of cv;
select p.id from products p join publish_queue q on q.product_id=p.id join reviewed_input x on x.queue_id=q.id for update of p;
do $$
begin
 if not exists(select 1 from pinterest_publish_settings where singleton and enabled and access_tier='standard') then raise exception 'Enabled Standard settings required'; end if;
 if exists(select 1 from reviewed_input where checked_at < now()-interval '24 hours' or checked_at>now()) then raise exception 'Fixed approval expired'; end if;
 if (select count(*) from reviewed_input x join publish_queue q on q.id=x.queue_id join products p on p.id=q.product_id and p.shop_id=q.shop_id join shops s on s.id=q.shop_id join content_variants cv on cv.id=q.content_variant_id and cv.product_id=p.id and cv.shop_id=s.id join social_accounts a on a.id=q.social_account_id
 where q.platform='pinterest' and cv.platform='pinterest' and q.status in ('draft','ready') and cv.status in ('draft','ready') and s.status='active' and a.active and a.handle=x.handle and a.platform='pinterest' and s.shop_name=x.shop and p.etsy_listing_id=x.listing_id and p.etsy_url=x.source_url and cv.destination_url=x.destination_url and cv.board_or_category=x.category and cv.image_url is not distinct from x.image_url and cv.title=x.title and cv.body=x.body
 and exists(select 1 from shop_social_accounts m where m.shop_id=s.id and m.social_account_id=a.id and m.platform='pinterest' and m.active)
 and exists(select 1 from pinterest_oauth_credentials cr where cr.social_account_id=a.id and lower(cr.pinterest_username)=lower(a.handle))
 and not exists(select 1 from publish_history h where h.product_id=p.id and h.platform='pinterest')
 and not exists(select 1 from pinterest_publish_attempts pa where pa.queue_id=q.id)) <> 5 then raise exception 'Expected 5 unchanged, mapped, unattempted drafts'; end if;
 if exists(select 1 from pinterest_publish_reviews rev join reviewed_input x on rev.queue_id=x.queue_id where rev.board_id<>x.board_id or rev.snapshot<>pinterest_publish_snapshot(x.queue_id)) then raise exception 'Existing review differs'; end if;
end $$;
update products p set listing_status='active',last_seen_at=x.checked_at from publish_queue q join reviewed_input x on x.queue_id=q.id where p.id=q.product_id;
update content_variants cv set status=case when x.board_id is null then 'draft'::content_status else 'ready'::content_status end,title=x.new_title,body=x.new_body,image_url=x.new_image_url from publish_queue q join reviewed_input x on x.queue_id=q.id where cv.id=q.content_variant_id;
insert into pinterest_publish_reviews(queue_id,board_id,snapshot,listing_checked_at,source_url)
select x.queue_id,x.board_id,pinterest_publish_snapshot(x.queue_id),x.checked_at,x.source_url from reviewed_input x where x.board_id is not null on conflict(queue_id) do nothing;
update publish_queue q set status='ready',updated_at=now() from reviewed_input x where q.id=x.queue_id and q.status='draft' and x.board_id is not null;
select json_build_object('queue_id',q.id,'status',q.status,'board_id',rev.board_id,'snapshot_matches',rev.snapshot=pinterest_publish_snapshot(q.id),'listing_checked_at',rev.listing_checked_at) from publish_queue q join reviewed_input x on x.queue_id=q.id left join pinterest_publish_reviews rev on rev.queue_id=q.id;
select json_build_object('public_publish_enabled',enabled) from pinterest_publish_settings where singleton;
commit;
